&Options = new() &OptionsDesc = new() &OptionIndexes = new() LoadWWPContext.Call(&WWPContext)
Do 'LoadGridState' Do Case Case &DDOName.ToUpper() = !'DDO_PRODDESCRICAO' Do 'LoadprodDescricaoOptions' Case &DDOName.ToUpper() = !'DDO_PRODTIPO' Do 'LoadprodTipoOptions' Case &DDOName.ToUpper() = !'DDO_PRODORIGEM' Do 'LoadprodOrigemOptions' Case &DDOName.ToUpper() = !'DDO_PRODCODIGOTIPOREMESSA' Do 'LoadprodCodigoTipoRemessaOptions' EndCase
