Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsprodutosWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsprodutosWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsprodutosWWGridState")) Endif
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFPRODCODIGO" &TFprodCodigo.FromString(&GridStateFilterValue.Value) &TFprodCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFPRODDESCRICAO" &TFprodDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPRODDESCRICAO_SEL" &TFprodDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPRODPESOCONSUMO" &TFprodPesoConsumo.FromString(&GridStateFilterValue.Value) &TFprodPesoConsumo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFPRODPESOESTOCAGEM" &TFprodPesoEstocagem.FromString(&GridStateFilterValue.Value) &TFprodPesoEstocagem_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFPRODTIPO" &TFprodTipo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPRODTIPO_SEL" &TFprodTipo_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPRODORIGEM" &TFprodOrigem.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPRODORIGEM_SEL" &TFprodOrigem_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPRODCLASSIFICACAO_SEL" &TFprodClassificacao_SelsJson = &GridStateFilterValue.Value &TFprodClassificacao_Sels.FromJson(&TFprodClassificacao_SelsJson) Case &GridStateFilterValue.Name = !"TFPRODCODIGOTIPOREMESSA" &TFprodCodigoTipoRemessa.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPRODCODIGOTIPOREMESSA_SEL" &TFprodCodigoTipoRemessa_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPRODSTATUS_SEL" &TFprodStatus_SelsJson = &GridStateFilterValue.Value &TFprodStatus_Sels.FromJson(&TFprodStatus_SelsJson) EndCase EndFor If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'PRODCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &prodCodigo1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'PRODDESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &prodDescricao1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'PRODTIPO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &prodTipo1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'PRODORIGEM' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &prodOrigem1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'PRODCLASSIFICACAO' &prodClassificacao1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'PRODSTATUS' &prodStatus1.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'PRODCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &prodCodigo2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'PRODDESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &prodDescricao2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'PRODTIPO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &prodTipo2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'PRODORIGEM' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &prodOrigem2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'PRODCLASSIFICACAO' &prodClassificacao2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'PRODSTATUS' &prodStatus2.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'PRODCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &prodCodigo3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'PRODDESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &prodDescricao3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'PRODTIPO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &prodTipo3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'PRODORIGEM' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &prodOrigem3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'PRODCLASSIFICACAO' &prodClassificacao3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'PRODSTATUS' &prodStatus3.FromString(&GridStateDynamicFilter.Value) EndCase EndIf EndIf EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadprodDescricaoOptions'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&TFprodDescricao = &SearchTxt &TFprodDescricao_Sel.SetEmpty() For Each trnsprodutos Order prodDescricao using trnsprodutosWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &prodCodigo1, &prodDescricao1, &prodTipo1, &prodOrigem1 , &prodClassificacao1, &prodStatus1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2, &prodCodigo2 , &prodDescricao2, &prodTipo2, &prodOrigem2, &prodClassificacao2, &prodStatus2, &DynamicFiltersEnabled3 , &DynamicFiltersSelector3, &DynamicFiltersOperator3, &prodCodigo3, &prodDescricao3, &prodTipo3, &prodOrigem3 , &prodClassificacao3, &prodStatus3, &TFprodCodigo, &TFprodCodigo_To, &TFprodDescricao, &TFprodDescricao_Sel , &TFprodPesoConsumo, &TFprodPesoConsumo_To, &TFprodPesoEstocagem, &TFprodPesoEstocagem_To, &TFprodTipo, &TFprodTipo_Sel , &TFprodOrigem, &TFprodOrigem_Sel, &TFprodClassificacao_Sels, &TFprodCodigoTipoRemessa, &TFprodCodigoTipoRemessa_Sel, &TFprodStatus_Sels) Where prefCodigo = &prefCodigo
&count = 0 For Each trnsprodutos Order prodDescricao &count += 1 EndFor If not prodDescricao.IsEmpty() &Option = prodDescricao
&Options.Add(&Option) &OptionIndexes.Add(trim(&count.ToFormattedString())) EndIf If &Options.Count = 50 Exit EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadprodTipoOptions'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
