&count = 0 For Each trnsprodutos Order prodTipo &count += 1 EndFor If not prodGrupdescricao.IsEmpty() &Option = prodTipo.ToString() &OptionDesc = prodGrupdescricao
&InsertIndex = 1 Do while &InsertIndex <= &Options.Count AND &OptionsDesc.Item(&InsertIndex) < &OptionDesc &InsertIndex = &InsertIndex + 1 EndDo &Options.Add(&Option, &InsertIndex) &OptionsDesc.Add(&OptionDesc, &InsertIndex) &OptionIndexes.Add(trim(&count.ToFormattedString()), &InsertIndex) EndIf If &Options.Count = 50 Exit EndIf EndFor
